"use client"

import * as React from "react"

interface CommandPaletteContextType {
  isSearchOpen: boolean
  setIsSearchOpen: (open: boolean) => void
  isQuickCreateOpen: boolean
  setIsQuickCreateOpen: (open: boolean) => void
  toggleSearch: () => void
  toggleQuickCreate: () => void
}

const CommandPaletteContext = React.createContext<CommandPaletteContextType | undefined>(undefined)

export function CommandPaletteProvider({ children }: { children: React.ReactNode }) {
  const [isSearchOpen, setIsSearchOpen] = React.useState(false)
  const [isQuickCreateOpen, setIsQuickCreateOpen] = React.useState(false)

  const toggleSearch = React.useCallback(() => setIsSearchOpen((prev) => !prev), [])
  const toggleQuickCreate = React.useCallback(() => setIsQuickCreateOpen((prev) => !prev), [])

  React.useEffect(() => {
    const down = (e: KeyboardEvent) => {
      if (e.key === "k" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault()
        toggleSearch()
      }
    }
    document.addEventListener("keydown", down)
    return () => document.removeEventListener("keydown", down)
  }, [toggleSearch])

  return (
    <CommandPaletteContext.Provider
      value={{
        isSearchOpen,
        setIsSearchOpen,
        isQuickCreateOpen,
        setIsQuickCreateOpen,
        toggleSearch,
        toggleQuickCreate,
      }}
    >
      {children}
    </CommandPaletteContext.Provider>
  )
}

export function useCommandPalette() {
  const context = React.useContext(CommandPaletteContext)
  if (context === undefined) {
    throw new Error("useCommandPalette must be used within a CommandPaletteProvider")
  }
  return context
}
